SourceCode.Declaration:
/// <summary>
/// This is an extension class for the VendParameters form METVendParameters datasource.
/// </summary>
[ExtensionOf(formDataSourceStr(VendParameters, METVendParameters))]
final class METVendParameters_METVendParametersDS_Extension
{
}

Method.Source:
/// <summary>
/// Enable/disable the EnableMetcashMatchingLogic control.
/// </summary>
public void init()
{
    next init();

    FormControl taxinvTotToleranceCtrl = this.formRun().design(1).controlName(formControlStr(VendParameters, METVendParameters_TaxInvTotalsToleranceDollar));
    FormControl enableMetMatchCtrl = this.formRun().design(1).controlName(formControlStr(VendParameters, METVendParameters_EnableMetcashMatchingLogic));

    METVendParameters metVendparm = METVendParameters::find();
    VendParameters vendparm = VendParameters::find();

    if (!vendparm.UseTotalPriceMatching)
    {
        enableMetMatchCtrl.enabled(true);

        if (metVendparm.EnableMetcashMatchingLogic)
        {
            taxinvTotToleranceCtrl.enabled(true);
        }
        else
        {
            taxinvTotToleranceCtrl.enabled(false);
        }
    }
    else
    {
        metVendparm.EnableMetcashMatchingLogic = NoYes::No;
        enableMetMatchCtrl.enabled(false);
        taxinvTotToleranceCtrl.enabled(false);
    }
}
